// Тест с сервоприводом (без драйвера!)
#include <Servo.h>

Servo myServo;

void setup() {
    myServo.attach(9);  // Сервопривод на пин 9
    Serial.begin(115200);
}

void loop() {
    if (Serial.available()) {
        char cmd = Serial.read();

        if (cmd == 'f') {  // Вперед
            myServo.write(180);  // Максимальный угол
            delay(1000);
            Serial.println("Forward");
        }
        else if (cmd == 'b') {  // Назад
            myServo.write(0);  // Минимальный угол
            delay(1000);
            Serial.println("Backward");
        }
        else if (cmd == 't') {  // Тест
            myServo.write(180);
            delay(1000);
            myServo.write(0);
            delay(1000);
            myServo.write(90);  // Средняя позиция
            Serial.println("Test complete");
        }
    }
}
